import { useContext, useEffect, useState } from "react";

//Context and tools
import { userContext } from "../../UserProvider";
import { extractAcronym } from "../../utils";
import { findAvatarDB, findUserNameDB } from "../../firebase/ReadWriteDB";
import axiosInstance from "../../axiosInstance";

//Components and styles
import ScreenTitle from "../base-components/ScreenTitle/ScreenTitle";
import ChatRoom from "../ChatRoom/ChatRoom";
import SearchBar from "../base-components/SearchBar/SearchBar";
import "./ChatList.css"


export default function ChatList(props){

    
    const [chatThumbnails, setChatThumbnails] = useState([]);
    const {user, loading, fetchImage} = useContext(userContext);
    const [chatList, setChatList] = useState([]);
    const [selectedChat, setSelectedChat] = useState(props.preSelectedChat || null);
    const [isSearching, setIsSearching] = useState(false);

    //Search
    const [searchValue, setSearchValue] = useState("");
    //const [filteredChatList, setFilteredChatList] = useState([]);

    
    useEffect(()=>{
        const fetchChatList = async () => {
            const limit = 20;
            try{
                const response = await axiosInstance.get(`/chats/?userId=${user.uid}&limit=${limit}`);
                if (response.status===200){
                    //DEBUG: console.log(response.data.message);
                    //DEBUG: console.log(response.data.chats);
                    setChatList(response.data.chats);
                }
            }
            catch(err){
                console.log(err);
                console.log(err.response?.data?.message);
            }
        }
        if(!isSearching)
            fetchChatList();
        else 
            return;
    }, [user, isSearching]);
    
    useEffect(() => {
        const fetchChatThumbnails = async (limit=-1) => {
            if(limit<0 && chatList){
                if(!user) return;
                //DEBUG: console.log("Attempting to pull users's chats list names/images")
                const thumbnails = await Promise.all(chatList.map(async (chatItem) => {
                    let avatar = chatItem.isGroupChat
                    ? await findAvatarDB(chatItem.creator)
                    : await findAvatarDB(chatItem.participants.find(member => member !== user?.uid));

                    if(chatItem.group?.logo && chatItem.isGroupChat){
                        //DEBUG: console.log("Attempting to fetch group logo");
                        const fetchedAvatar = await fetchImage(chatItem.group?.logo, false);
                        if(fetchedAvatar)
                            avatar = fetchedAvatar;
                    }
                    else{
                        if(!avatar.includes("static")){
                            const fetchedAvatar = await fetchImage(avatar, false);
                            if(fetchedAvatar)
                                avatar = fetchedAvatar;
                        }
                    }

                    //DEBUG: console.log(avatar);
                    //DEBUG: console.log(chatItem);
                    let label = "N/A"
                    try{
                        if(!chatItem.isGroupChat) 
                            label = await findUserNameDB(chatItem.participants.find(member => member !== user?.uid));
                        else {
                            const response = await axiosInstance.get(`/groups/search/${chatItem.group._id}`);
                            if(response.status===200){
                                label = response.data.group.name;
                                //DEBUG: console.log(label);
                            }
                        }
                    }catch(err){
                        console.log(err);
                    }
                    if(label?.length>10) {
                        if(label.split(" ").length>1)
                            label = extractAcronym(label).slice(0,3);          
                        else
                            label = label.slice(0,7);
                    }
                    //DEBUG: console.log(`label: ${label} avatar: ${avatar}`);

                    return {avatar, label, chatId: chatItem._id};
                }));
                setChatThumbnails(thumbnails);
            }
        }
       
        fetchChatThumbnails();
    }, [chatList , user, fetchImage]);

    const openChat =(chatId)=>{
        if(props.handleChatSelected) {
            props.handleChatSelected(chatId);
            return;
        }
        if(selectedChat === chatId ){
            setSelectedChat(null);
        } else {
            setSelectedChat(chatId);
        }
    }

    const searchChats = (searchQuery) => {
        if(!searchQuery.trim()) return console.log('Search query is empty');
        console.log(`Attempting to find chats with the query: ${searchQuery}`);
        console.log(chatList);
        return Promise.all(chatList.map(async (chatItem) => {
            if (chatItem.isGroupChat){
                if(chatItem.group.name.toLowerCase().includes(searchQuery.toLowerCase()))
                    return chatItem;
            }
            else{
                const participant = await findUserNameDB(chatItem.participants.find(member => member !== user?.uid));
                if(participant.toLowerCase().includes(searchQuery.toLowerCase()))
                    return chatItem;
            }
            return null;
        })).then((filteredChats)=>{
            setChatList(filteredChats.filter(chatItem => chatItem !== null));
        }).catch(err => console.log(err));
        
    }
    
    if(loading) return <div>Loading...</div>;
    
    return(
    <div className={`docked-container ${props.className || ""}`} id="chat-list-container">
        <div className="chat-list-search-container">
            <SearchBar
                value={searchValue}
                onChange={setSearchValue}
                onSearch={searchChats}
                onIsSearching={setIsSearching}
                />
        </div>
        <ul className="chat-list">
            {chatThumbnails.map((thumbnail, index) =>{ 
            
            const isExpanded = selectedChat === thumbnail.chatId;
            return (
                <li className={`chat-item ${isExpanded? "expanded":""}`} id="chat-i" key={index}>
                    <div className="chat-item-header" onClick={()=>openChat(thumbnail.chatId)}>
                        <img id="chat-avatar" src={thumbnail.avatar} alt={thumbnail.label} />
                        <ScreenTitle title={thumbnail.label} designClass="chat-title"/>
                    </div>
                    {isExpanded &&
                        <div className="chat-room-mini-view">
                            <ChatRoom chatId={thumbnail.chatId} miniView={true}/>
                        </div>
                    }
                </li>)
            })}
            
        </ul>    
    </div>

    );
}